-- Nineall HR — seed: 16 demo employees across departments with varied employment types.
-- Demo data only. Names are fictional. Safe to re-run (ON CONFLICT DO NOTHING per employee_code).

on conflict (org_id, employee_code) do nothing;

-- Manager wiring: EMP-003 leads Marketing, EMP-006 leads Warehouse, EMP-002 leads HR.
update teams set manager_employee_id = '00000000-0000-0000-0000-000000010003' where id = '00000000-0000-0000-0000-000000000402';
update teams set manager_employee_id = '00000000-0000-0000-0000-000000010006' where id = '00000000-0000-0000-0000-000000000404';
update teams set manager_employee_id = '00000000-0000-0000-0000-000000010002' where id = '00000000-0000-0000-0000-000000000407';

update employees set manager_employee_id = '00000000-0000-0000-0000-000000010003' where id in ('00000000-0000-0000-0000-000000010008', '00000000-0000-0000-0000-000000010013');
update employees set manager_employee_id = '00000000-0000-0000-0000-000000010006' where id in ('00000000-0000-0000-0000-000000010010', '00000000-0000-0000-0000-000000010016');
update employees set manager_employee_id = '00000000-0000-0000-0000-000000010002' where id = '00000000-0000-0000-0000-000000010001';

on conflict (employee_id, effective_date) do nothing;

-- Default shift assignment: everyone on the normal 08:30-17:30 shift at HQ for the current week.
select '00000000-0000-0000-0000-000000000001', e.id, d::date, '00000000-0000-0000-0000-000000000601', '00000000-0000-0000-0000-000000000201', 'schedule'
from employees e
cross join generate_series(current_date - interval '6 days', current_date, interval '1 day') as d
where e.org_id = '00000000-0000-0000-0000-000000000001'
  and extract(isodow from d) < 6 -- Mon-Fri only
on conflict (employee_id, work_date) do nothing;
